css:
.cd-preview-wrapper {
  font-family: Arial, sans-serif;
  color: #0f172a;
  font-size: 12px;
}

.cd-card {
  margin: 12px 0 18px 0;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  overflow: hidden;
  background: #ffffff;
  page-break-inside: avoid;
  break-inside: avoid;
}

.cd-header {
  text-align: center;
  padding: 10px 12px 8px 12px;
  border-bottom: 3px solid #1f6e8c;
  background: #ffffff;
}

.cd-title-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
}

.cd-title-en {
  flex: 1;
  text-align: left;
  font-size: 20px;
  font-weight: 900;
  color: #0c4a6e;
  line-height: 1.25;
}

.cd-title-ar {
  flex: 1;
  text-align: right;
  font-size: 18px;
  font-weight: 900;
  color: #0c4a6e;
  direction: rtl;
  line-height: 1.25;
}

.cd-info-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 10px 10px 8px 10px;
}

.cd-badge {
  background: #f1f5f9;
  border-radius: 999px;
  padding: 5px 14px;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.cd-badge strong {
  color: #1f6e8c;
  font-weight: 900;
}

.cd-badge-warning {
  background: #fff7ed;
  border-color: #fed7aa;
  color: #9a3412;
}

.cd-badge-danger {
  background: #fef2f2;
  border-color: #fecaca;
  color: #991b1b;
}

.cd-badge-success {
  background: #f0fdf4;
  border-color: #bbf7d0;
  color: #166534;
}

.cd-rtl {
  direction: rtl;
}

.cd-operation-header {
  padding: 9px 12px 8px 12px;
  border-bottom: 2px solid #e6f7ff;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
}

.cd-operation-title-en {
  font-size: 14px;
  font-weight: 900;
  color: #1f6e8c;
}

.cd-operation-title-ar {
  font-size: 13px;
  font-weight: 900;
  direction: rtl;
  color: #2c3e50;
}

.cd-table {
  width: 100%;
  border-collapse: collapse;
  margin: 0;
  font-size: 12px;
}

.cd-table th {
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  padding: 7px 6px;
  text-align: center;
  font-weight: 900;
  color: #111827;
  line-height: 1.25;
}

.cd-table td {
  border: 1px solid #e2e8f0;
  padding: 7px 6px;
  text-align: center;
  vertical-align: middle;
  line-height: 1.3;
}

.cd-table .item-col {
  text-align: left;
  font-weight: 800;
  color: #0f172a;
  width: 35%;
}

.cd-number {
  font-weight: 900;
  color: #0f172a;
}

.cd-uom-small {
  font-size: 9.5px;
  font-weight: 800;
  color: #475569;
  margin-left: 3px;
}

.cd-small {
  font-size: 10.5px;
  color: #64748b;
  font-weight: 700;
  margin-top: 2px;
}

.item-name-ar {
  direction: rtl;
  text-align: right;
  font-weight: 800;
  color: #334155;
  margin-top: 3px;
  font-size: 11px;
}

.bi-head {
  line-height: 1.25;
}

.bi-head .en {
  font-weight: 900;
  font-size: 11px;
}

.bi-head .ar {
  font-weight: 800;
  font-size: 11px;
  direction: rtl;
  color: #334155;
  margin-top: 2px;
}

.cd-muted {
  color: #64748b;
  font-weight: 800;
}

.cd-danger {
  color: #b91c1c;
  font-weight: 900;
}

.cd-warning {
  color: #9a3412;
  font-weight: 900;
}

.cd-success {
  color: #166534;
  font-weight: 900;
}

.cd-icon-up {
  display: inline-block;
  color: #15803d;
  font-weight: 900;
  font-size: 13px;
  margin-right: 3px;
}

.cd-icon-down {
  display: inline-block;
  color: #b91c1c;
  font-weight: 900;
  font-size: 13px;
  margin-right: 3px;
}

.cd-icon-ok {
  display: inline-block;
  color: #166534;
  font-weight: 900;
  font-size: 13px;
  margin-right: 3px;
}

.cd-diff-up {
  color: #15803d;
  font-weight: 900;
}

.cd-diff-down {
  color: #b91c1c;
  font-weight: 900;
}

.cd-diff-ok {
  color: #166534;
  font-weight: 900;
}

.cd-notes-block {
  margin: 8px 10px 10px 10px;
  padding: 0;
  border: 0;
  background: transparent;
  page-break-inside: avoid;
}

.cd-notes-title {
  font-size: 11px;
  font-weight: 900;
  color: #0c4a6e;
  margin-bottom: 4px;
}

.cd-note-line {
  display: block;
  padding: 2px 0;
  border: 0;
  background: transparent;
  font-size: 11px;
  line-height: 1.45;
  color: #334155;
  font-weight: 700;
  white-space: pre-wrap;
}

.cd-calc-block {
  margin: 8px 10px 10px 10px;
  padding: 8px 10px;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  background: #f8fafc;
  page-break-inside: avoid;
  break-inside: avoid;
}

.cd-dish-options-block {
  margin-top: 10px;
  background: #ffffff;
}

.cd-calc-title {
  font-size: 12px;
  font-weight: 900;
  color: #0c4a6e;
  margin-bottom: 8px;
}

.cd-calc-section {
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px dashed #cbd5e1;
}

.cd-calc-section:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.cd-calc-section-title {
  font-size: 11px;
  font-weight: 900;
  color: #1f6e8c;
  margin-bottom: 4px;
}

.cd-calc-line {
  font-size: 10.5px;
  line-height: 1.45;
  color: #0f172a;
  margin: 2px 0;
}

.cd-calc-material {
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px solid #e2e8f0;
}

.cd-calc-material:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.cd-receiving-box {
  margin-top: 6px;
  padding: 6px 7px;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  background: #ffffff;
}

.cd-impact-title {
  margin-top: 8px;
  margin-bottom: 4px;
  font-size: 10.8px;
  font-weight: 900;
  color: #334155;
}

.cd-mini-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 5px;
  margin-bottom: 8px;
  font-size: 10.5px;
}

.cd-mini-table th {
  border: 1px solid #cbd5e1;
  background: #f1f5f9;
  padding: 5px;
  font-weight: 900;
  text-align: center;
}

.cd-mini-table td {
  border: 1px solid #e2e8f0;
  padding: 5px;
  text-align: center;
  vertical-align: middle;
}

.cd-output-table {
  margin-top: 10px;
}

.cd-output-number {
  font-size: 16px;
  font-weight: 900;
  color: #0f172a;
}

.cd-output-uom {
  font-size: 11px;
  font-weight: 800;
  color: #334155;
}

.cd-coverage-warning {
  font-size: 12px;
  font-weight: 900;
  color: #9a3412;
}

.cd-coverage-danger {
  font-size: 12px;
  font-weight: 900;
  color: #b91c1c;
}

.cd-coverage-success {
  font-size: 12px;
  font-weight: 900;
  color: #166534;
}

@media print {
  .cd-card,
  .cd-calc-block,
  .cd-notes-block,
  .cd-receiving-box {
    page-break-inside: avoid;
    break-inside: avoid;
  }

  .cd-header,
  .cd-badge,
  .cd-operation-header,
  .cd-table th,
  .cd-mini-table th,
  .cd-calc-block {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}

html:
{# ============================================================
   Print Format Name: Catering Dish Calculation
   DocType: Catering Dish

   Key Logic:
   1) Recipe Ratio materials calculate operation runs and output.
      Example: Spaghetti.
   2) Fixed Once materials do not affect runs/output.
      They are issued once.
   3) Fixed Every N Runs materials do not affect runs/output.
      They are issued by run frequency.
      Example: 17 Litre oil every 3 runs.
   4) Use Full Warehouse Issue Qty affects Recipe Ratio materials
      when calculating operation basis.
   5) operation_display_uom_mode controls display only:
      - Material UOM
      - Receiving UOM
      - Both
   ============================================================ #}

{% set person_qty = frappe.utils.flt(doc.test_person_qty or 100) %}
{% set requires_operation = frappe.utils.cint(doc.requires_workstation or 0) %}
{% set input_same_as_output = frappe.utils.cint(doc.input_qtyuom_same_as_output or 0) %}
{% set use_full_warehouse_issue_qty = frappe.utils.cint(doc.use_full_warehouse_issue_qty or 0) %}

{% set base_output_uom = doc.output_container_uom or "Output" %}
{% set output_capacity_qty = frappe.utils.flt(doc.output_container_capacity_qty or 0) %}
{% set output_capacity_uom = doc.output_container_capacity_uom or "" %}
{% set output_rounding = doc.output_rounding_method or "Round Up" %}

{% set workstation_load_qty = frappe.utils.flt(doc.workstation_load_qty or 0) %}
{% set workstation_load_uom = doc.workstation_load_uom or "" %}

{% set operation_uom = base_output_uom %}
{% if input_same_as_output and workstation_load_uom %}
  {% set operation_uom = workstation_load_uom %}
{% endif %}

{% set batch_round_uoms = [
  "Piece", "Pieces", "Pcs", "Nos",
  "Unit", "Units",
  "Pouch", "Pouches",
  "Egg", "Eggs",
  "Tray", "Trays",
  "egg tray", "Egg Tray",
  "Carton", "Cartons",
  "Basket", "Baskets"
] %}

{% set mode_ns = namespace(batch_output=false) %}

{% if requires_operation
      and not input_same_as_output
      and workstation_load_qty > 0
      and base_output_uom
      and output_capacity_qty > 0
      and output_capacity_uom == base_output_uom %}
  {% set mode_ns.batch_output = true %}
{% endif %}

{% set run_ns = namespace(
  can=false,
  raw=0,
  qty=0,
  basis_qty=0,
  basis_uom="",
  formula="",
  full_runs=0,
  last_run_qty=0
) %}

{% macro fmt(value) %}
  {% set v = frappe.utils.flt(value or 0) %}
  {% if v == (v|int) %}
    {{ "{:,}".format(v|int) }}
  {% else %}
    {{ "{:,.3f}".format(v).rstrip("0").rstrip(".") }}
  {% endif %}
{% endmacro %}

{% macro yes_no(value) %}
  {% if frappe.utils.cint(value or 0) %}
    Yes
  {% else %}
    No
  {% endif %}
{% endmacro %}

{% macro uom_short(uom) %}
  {% if (uom or "") == "Litre" %}
    L
  {% elif (uom or "") == "Liter" %}
    L
  {% elif (uom or "") == "Kilogram" %}
    Kg
  {% else %}
    {{ uom or "" }}
  {% endif %}
{% endmacro %}

{% macro round_text(method) %}
  {% if method == "Round Down" %}
    Round Down
  {% elif method == "Half Round" %}
    Half Round
  {% elif method == "No Rounding" %}
    No Rounding
  {% else %}
    Round Up
  {% endif %}
{% endmacro %}

{% macro rounded_qty(raw, method) %}
  {% set raw = frappe.utils.flt(raw or 0) %}
  {% set raw_int = raw|int %}
  {% set raw_decimal = raw - raw_int %}

  {% if method == "No Rounding" %}
    {{ raw }}
  {% elif method == "Round Down" %}
    {{ raw_int }}
  {% elif method == "Half Round" %}
    {% if raw_decimal >= 0.5 %}
      {{ raw_int + 1 }}
    {% else %}
      {{ raw_int }}
    {% endif %}
  {% else %}
    {% if raw > raw_int %}
      {{ raw_int + 1 }}
    {% else %}
      {{ raw_int }}
    {% endif %}
  {% endif %}
{% endmacro %}

{% macro rounded_up(raw) %}
  {% set raw = frappe.utils.flt(raw or 0) %}
  {% set raw_int = raw|int %}

  {% if raw > raw_int %}
    {{ raw_int + 1 }}
  {% else %}
    {{ raw_int }}
  {% endif %}
{% endmacro %}

{# ============================================================
   Display Operation Qty by selected display mode
   Material UOM:
     200 Piece
   Receiving UOM:
     16 Carton + 8 Piece
   Both:
     16 Carton + 8 Piece (200 Piece)
   ============================================================ #}

{% macro operation_qty_display(row, qty) %}
  {% set q = frappe.utils.flt(qty or 0) %}
  {% set display_mode = row.operation_display_uom_mode or "Receiving UOM" %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
  {% set rec_uom = row.receiving_capacity_uom or "" %}
  {% set base_uom = row.uom or "" %}

  {% if display_mode == "Material UOM" or cap_qty <= 0 or not rec_uom %}
    {{ fmt(q) }} {{ base_uom }}

  {% else %}
    {% set full_pack_qty = (q / cap_qty)|int %}
    {% set remainder_qty = q - (full_pack_qty * cap_qty) %}

    {% if remainder_qty < 0.0001 %}
      {% set remainder_qty = 0 %}
    {% endif %}

    {% if full_pack_qty > 0 and remainder_qty > 0 %}
      {{ fmt(full_pack_qty) }} {{ rec_uom }} + {{ fmt(remainder_qty) }} {{ base_uom }}
    {% elif full_pack_qty > 0 %}
      {{ fmt(full_pack_qty) }} {{ rec_uom }}
    {% else %}
      {{ fmt(q) }} {{ base_uom }}
    {% endif %}

    {% if display_mode == "Both" %}
      <span class="cd-small-inline">({{ fmt(q) }} {{ base_uom }})</span>
    {% endif %}
  {% endif %}
{% endmacro %}

{% macro operation_qty_display_note(row, qty) %}
  {% set q = frappe.utils.flt(qty or 0) %}
  {% set display_mode = row.operation_display_uom_mode or "Receiving UOM" %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
  {% set rec_uom = row.receiving_capacity_uom or "" %}
  {% set base_uom = row.uom or "" %}

  {% if display_mode != "Material UOM" and cap_qty > 0 and rec_uom and q > 0 %}
    {% set raw = q / cap_qty %}
    <div class="cd-small">
      {{ fmt(q) }} {{ base_uom }}
      ÷
      {{ fmt(cap_qty) }}
      =
      {{ fmt(raw) }} {{ rec_uom }}
    </div>
  {% endif %}
{% endmacro %}

{% macro material_operation_mode(row) %}
  {{ row.operation_qty_mode or "Recipe Ratio" }}
{% endmacro %}

{% macro fixed_operation_times(row) %}
  {% set mode = row.operation_qty_mode or "Recipe Ratio" %}
  {% set freq = frappe.utils.cint(row.operation_run_frequency or 1) %}

  {% if freq <= 0 %}
    {% set freq = 1 %}
  {% endif %}

  {% if mode == "Fixed Once" %}
    1
  {% elif mode == "Fixed Every N Runs" %}
    {% if run_ns.can and run_ns.qty > 0 %}
      {{ rounded_up(run_ns.qty / freq) }}
    {% else %}
      0
    {% endif %}
  {% else %}
    0
  {% endif %}
{% endmacro %}

{% macro fixed_operation_required_qty(row) %}
  {% set mode = row.operation_qty_mode or "Recipe Ratio" %}
  {% set fixed_qty = frappe.utils.flt(row.fixed_operation_qty or 0) %}

  {% if mode == "Fixed Once" %}
    {{ fixed_qty }}
  {% elif mode == "Fixed Every N Runs" %}
    {% set times = frappe.utils.flt(fixed_operation_times(row) or 0) %}
    {{ fixed_qty * times }}
  {% else %}
    0
  {% endif %}
{% endmacro %}

{# ============================================================
   Required Qty
   ============================================================ #}

{% macro material_required_qty(row, output_qty) %}
  {% set op_mode = row.operation_qty_mode or "Recipe Ratio" %}
  {% set base = row.material__calculation_base or "Per Person" %}

  {% if op_mode == "Fixed Once" or op_mode == "Fixed Every N Runs" %}
    {{ fixed_operation_required_qty(row) }}

  {% elif base == "Per Output" %}
    {{ frappe.utils.flt(row.qty_per_output or 0) * frappe.utils.flt(output_qty or 0) }}

  {% elif base == "Output Driver" %}
    {% if frappe.utils.flt(row.qty_per_person or 0) > 0 %}
      {{ frappe.utils.flt(row.qty_per_person or 0) * person_qty }}
    {% else %}
      {{ frappe.utils.flt(row.qty_per_output or 0) * frappe.utils.flt(output_qty or 0) }}
    {% endif %}

  {% elif base == "Per Person" %}
    {{ frappe.utils.flt(row.qty_per_person or 0) * person_qty }}

  {% else %}
    0
  {% endif %}
{% endmacro %}

{% macro required_qty_note(row, required_qty, output_qty) %}
  {% set op_mode = row.operation_qty_mode or "Recipe Ratio" %}
  {% set base = row.material__calculation_base or "Per Person" %}

  {% if op_mode == "Fixed Once" %}
    <div class="cd-small">
      Fixed once:
      {{ operation_qty_display(row, row.fixed_operation_qty) }}
    </div>

  {% elif op_mode == "Fixed Every N Runs" %}
    {% set freq = frappe.utils.cint(row.operation_run_frequency or 1) %}
    {% if freq <= 0 %}
      {% set freq = 1 %}
    {% endif %}

    {% set times = frappe.utils.flt(fixed_operation_times(row) or 0) %}

    <div class="cd-small">
      {{ fmt(run_ns.qty) }} Runs
      ÷
      {{ fmt(freq) }}
      =
      {{ fmt(run_ns.qty / freq) }}
      →
      {{ fmt(times) }} times
    </div>

    <div class="cd-small">
      {{ fmt(times) }} × {{ operation_qty_display(row, row.fixed_operation_qty) }}
      =
      {{ operation_qty_display(row, required_qty) }}
    </div>

  {% elif base == "Per Person" %}
    <div class="cd-small">
      {{ fmt(person_qty) }} × {{ fmt(row.qty_per_person) }} = {{ fmt(required_qty) }} {{ uom_short(row.uom) }}
    </div>

  {% elif base == "Per Output" %}
    <div class="cd-small">
      {{ fmt(output_qty) }} {{ operation_uom }} × {{ fmt(row.qty_per_output) }} = {{ fmt(required_qty) }} {{ uom_short(row.uom) }}
    </div>

  {% elif base == "Output Driver" %}
    {% if frappe.utils.flt(row.qty_per_person or 0) > 0 %}
      <div class="cd-small">
        {{ fmt(person_qty) }} × {{ fmt(row.qty_per_person) }} = {{ fmt(required_qty) }} {{ uom_short(row.uom) }}
      </div>
    {% else %}
      <div class="cd-small">
        {{ fmt(output_qty) }} {{ operation_uom }} × {{ fmt(row.qty_per_output) }} = {{ fmt(required_qty) }} {{ uom_short(row.uom) }}
      </div>
    {% endif %}
  {% endif %}
{% endmacro %}

{# ============================================================
   Warehouse Issue
   ============================================================ #}

{% macro warehouse_issue_covered_qty(row, issue_qty) %}
  {% set required = frappe.utils.flt(issue_qty or 0) %}
  {% set small_qty = frappe.utils.flt(row.small_pack_qty or 0) %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
  {% set rounding = row.receiving_rounding_method or "Round Up" %}

  {% if required <= 0 %}
    0

  {% elif small_qty > 0 and row.small_pack_uom %}
    {% set raw = required / small_qty %}
    {% set pack_qty = frappe.utils.flt(rounded_qty(raw, rounding) or 0) %}
    {{ pack_qty * small_qty }}

  {% elif cap_qty > 0 and row.receiving_capacity_uom %}
    {% set raw = required / cap_qty %}
    {% set pack_qty = frappe.utils.flt(rounded_qty(raw, rounding) or 0) %}
    {{ pack_qty * cap_qty }}

  {% else %}
    {{ required }}
  {% endif %}
{% endmacro %}

{% macro warehouse_issue_display(row, issue_qty) %}
  {% set required = frappe.utils.flt(issue_qty or 0) %}
  {% set small_qty = frappe.utils.flt(row.small_pack_qty or 0) %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
  {% set rounding = row.receiving_rounding_method or "Round Up" %}

  {% if required <= 0 %}
    -

  {% elif small_qty > 0 and row.small_pack_uom %}
    {% set raw = required / small_qty %}
    {% set issue_pack_qty = frappe.utils.flt(rounded_qty(raw, rounding) or 0) %}
    {{ fmt(issue_pack_qty) }} {{ row.small_pack_uom }}

  {% elif cap_qty > 0 and row.receiving_capacity_uom %}
    {% set raw = required / cap_qty %}
    {% set issue_pack_qty = frappe.utils.flt(rounded_qty(raw, rounding) or 0) %}
    {{ fmt(issue_pack_qty) }} {{ row.receiving_capacity_uom }}

  {% else %}
    {{ fmt(required) }} {{ row.uom or "" }}
  {% endif %}
{% endmacro %}

{% macro warehouse_issue_note(row, issue_qty) %}
  {% set required = frappe.utils.flt(issue_qty or 0) %}
  {% set small_qty = frappe.utils.flt(row.small_pack_qty or 0) %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}
  {% set rounding = row.receiving_rounding_method or "Round Up" %}

  {% if required <= 0 %}
    <div class="cd-small">No warehouse issue</div>

  {% elif small_qty > 0 and row.small_pack_uom %}
    {% set raw = required / small_qty %}
    {% set issue_pack_qty = frappe.utils.flt(rounded_qty(raw, rounding) or 0) %}
    <div class="cd-small">
      {{ fmt(required) }} {{ row.uom }}
      ÷
      {{ fmt(small_qty) }}
      =
      {{ fmt(raw) }}
      →
      {{ fmt(issue_pack_qty) }} {{ row.small_pack_uom }}
    </div>
    <div class="cd-small">Warehouse issue rounding: {{ rounding }}</div>

  {% elif cap_qty > 0 and row.receiving_capacity_uom %}
    {% set raw = required / cap_qty %}
    {% set issue_pack_qty = frappe.utils.flt(rounded_qty(raw, rounding) or 0) %}
    <div class="cd-small">
      {{ fmt(required) }} {{ row.uom }}
      ÷
      {{ fmt(cap_qty) }}
      =
      {{ fmt(raw) }}
      →
      {{ fmt(issue_pack_qty) }} {{ row.receiving_capacity_uom }}
    </div>
    <div class="cd-small">Warehouse issue rounding: {{ rounding }}</div>

  {% else %}
    <div class="cd-small">
      Exact issue: {{ fmt(required) }} {{ row.uom }}
    </div>
  {% endif %}
{% endmacro %}

{# ============================================================
   Purchase Qty
   ============================================================ #}

{% macro purchase_qty_display(row, required_qty) %}
  {% set include_purchase = frappe.utils.cint(row.include_in_purchase or 0) %}
  {% set full_pack_only = frappe.utils.cint(row.purchase_full_pack_only or 0) %}
  {% set required = frappe.utils.flt(required_qty or 0) %}
  {% set large_qty = frappe.utils.flt(row.large_pack_qty or 0) %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}

  {% if not include_purchase %}
    -

  {% elif full_pack_only and large_qty > 0 and row.large_pack_uom %}
    {% set raw = required / large_qty %}
    {% set qty = frappe.utils.flt(rounded_up(raw) or 0) %}
    {% if qty <= 0 and required > 0 %}
      {% set qty = 1 %}
    {% endif %}
    {{ fmt(qty) }} {{ row.large_pack_uom }}

  {% elif full_pack_only and cap_qty > 0 and row.receiving_capacity_uom %}
    {% set raw = required / cap_qty %}
    {% set qty = frappe.utils.flt(rounded_up(raw) or 0) %}
    {% if qty <= 0 and required > 0 %}
      {% set qty = 1 %}
    {% endif %}
    {{ fmt(qty) }} {{ row.receiving_capacity_uom }}

  {% elif large_qty > 0 and row.large_pack_uom %}
    {% set raw = required / large_qty %}
    {{ fmt(raw) }} {{ row.large_pack_uom }}

  {% elif cap_qty > 0 and row.receiving_capacity_uom %}
    {% set raw = required / cap_qty %}
    {{ fmt(raw) }} {{ row.receiving_capacity_uom }}

  {% else %}
    {{ fmt(required) }} {{ row.uom or "" }}
  {% endif %}
{% endmacro %}

{% macro purchase_qty_note(row, required_qty) %}
  {% set include_purchase = frappe.utils.cint(row.include_in_purchase or 0) %}
  {% set full_pack_only = frappe.utils.cint(row.purchase_full_pack_only or 0) %}
  {% set required = frappe.utils.flt(required_qty or 0) %}
  {% set large_qty = frappe.utils.flt(row.large_pack_qty or 0) %}
  {% set cap_qty = frappe.utils.flt(row.receiving_capacity_qty or 0) %}

  {% if not include_purchase %}
    <div class="cd-small">No purchase</div>

  {% elif full_pack_only and large_qty > 0 %}
    {% set raw = required / large_qty %}
    {% set qty = frappe.utils.flt(rounded_up(raw) or 0) %}
    <div class="cd-small">
      {{ fmt(required) }} ÷ {{ fmt(large_qty) }} = {{ fmt(raw) }} → {{ fmt(qty) }} {{ row.large_pack_uom }}
    </div>
    <div class="cd-small">Full pack purchase only</div>

  {% elif full_pack_only and cap_qty > 0 %}
    {% set raw = required / cap_qty %}
    {% set qty = frappe.utils.flt(rounded_up(raw) or 0) %}
    <div class="cd-small">
      {{ fmt(required) }} ÷ {{ fmt(cap_qty) }} = {{ fmt(raw) }} → {{ fmt(qty) }} {{ row.receiving_capacity_uom }}
    </div>
    <div class="cd-small">Full pack purchase only</div>

  {% elif large_qty > 0 %}
    {% set raw = required / large_qty %}
    <div class="cd-small">
      {{ fmt(required) }} ÷ {{ fmt(large_qty) }} = {{ fmt(raw) }} {{ row.large_pack_uom }}
    </div>

  {% elif cap_qty > 0 %}
    {% set raw = required / cap_qty %}
    <div class="cd-small">
      {{ fmt(required) }} ÷ {{ fmt(cap_qty) }} = {{ fmt(raw) }} {{ row.receiving_capacity_uom }}
    </div>
  {% endif %}
{% endmacro %}

{# ============================================================
   Operation Qty
   ============================================================ #}

{% macro material_operation_qty(row, demand_qty, output_qty) %}
  {% set include_production = frappe.utils.cint(row.include_in_production or 0) %}
  {% set op_mode = row.operation_qty_mode or "Recipe Ratio" %}
  {% set fixed_qty = frappe.utils.flt(row.qty_per_output or 0) %}
  {% set output_count = frappe.utils.flt(output_qty or 0) %}

  {% if not include_production %}
    0

  {% elif op_mode == "Fixed Once" or op_mode == "Fixed Every N Runs" %}
    {{ fixed_operation_required_qty(row) }}

  {% elif fixed_qty > 0 and output_count > 0 %}
    {{ fixed_qty * output_count }}

  {% elif input_same_as_output and output_capacity_qty > 0 and output_count > 0 %}
    {{ output_capacity_qty * output_count }}

  {% else %}
    {{ frappe.utils.flt(demand_qty or 0) }}
  {% endif %}
{% endmacro %}

{% macro qty_per_output_display(row, required_qty, output_qty) %}
  {% set fixed_qty = frappe.utils.flt(row.qty_per_output or 0) %}
  {% set small_qty = frappe.utils.flt(row.small_pack_qty or 0) %}

  {% if input_same_as_output and workstation_load_qty > 0 %}
    {{ operation_qty_display(row, workstation_load_qty) }}

  {% elif fixed_qty > 0 %}
    {% if small_qty > 0 and row.small_pack_uom %}
      {% set pack_qty = fixed_qty / small_qty %}
      {{ fmt(pack_qty) }} {{ row.small_pack_uom }}
    {% else %}
      {{ operation_qty_display(row, fixed_qty) }}
    {% endif %}

  {% elif output_capacity_qty > 0 %}
    {{ operation_qty_display(row, output_capacity_qty) }}

  {% else %}
    {% set required = frappe.utils.flt(required_qty or 0) %}
    {% set output_count = frappe.utils.flt(output_qty or 0) %}

    {% if required <= 0 or output_count <= 0 %}
      -
    {% else %}
      {% set per_qty = required / output_count %}

      {% if small_qty > 0 and row.small_pack_uom %}
        {% set pack_raw = per_qty / small_qty %}
        {{ fmt(pack_raw) }} {{ row.small_pack_uom }}
      {% else %}
        {{ operation_qty_display(row, per_qty) }}
      {% endif %}
    {% endif %}
  {% endif %}
{% endmacro %}

{% macro qty_per_output_note(row, required_qty, output_qty) %}
  {% set fixed_qty = frappe.utils.flt(row.qty_per_output or 0) %}
  {% set small_qty = frappe.utils.flt(row.small_pack_qty or 0) %}

  {% if input_same_as_output and workstation_load_qty > 0 %}
    <div class="cd-small">
      Workstation load:
      {{ operation_qty_display(row, workstation_load_qty) }}
    </div>
    {{ operation_qty_display_note(row, workstation_load_qty) }}

  {% elif fixed_qty > 0 %}
    {% if small_qty > 0 and row.small_pack_uom %}
      {% set pack_qty = fixed_qty / small_qty %}
      <div class="cd-small">
        Fixed:
        {{ fmt(fixed_qty) }} {{ row.uom }}
        ÷
        {{ fmt(small_qty) }}
        =
        {{ fmt(pack_qty) }} {{ row.small_pack_uom }}
      </div>
    {% else %}
      <div class="cd-small">
        Fixed:
        {{ operation_qty_display(row, fixed_qty) }}
        per {{ operation_uom }}
      </div>
      {{ operation_qty_display_note(row, fixed_qty) }}
    {% endif %}

  {% elif output_capacity_qty > 0 %}
    <div class="cd-small">
      1 {{ operation_uom }} =
      {{ operation_qty_display(row, output_capacity_qty) }}
    </div>
    {{ operation_qty_display_note(row, output_capacity_qty) }}

  {% else %}
    {% set required = frappe.utils.flt(required_qty or 0) %}
    {% set output_count = frappe.utils.flt(output_qty or 0) %}

    {% if required > 0 and output_count > 0 %}
      {% set per_qty = required / output_count %}

      {% if small_qty > 0 and row.small_pack_uom %}
        {% set pack_raw = per_qty / small_qty %}
        <div class="cd-small">
          {{ fmt(required) }} {{ row.uom }}
          ÷
          {{ fmt(output_count) }} {{ operation_uom }}
          =
          {{ fmt(per_qty) }} {{ row.uom }}
          =
          {{ fmt(pack_raw) }} {{ row.small_pack_uom }}
        </div>
      {% else %}
        <div class="cd-small">
          {{ fmt(required) }} {{ row.uom }}
          ÷
          {{ fmt(output_count) }} {{ operation_uom }}
          =
          {{ operation_qty_display(row, per_qty) }}
        </div>
        {{ operation_qty_display_note(row, per_qty) }}
      {% endif %}
    {% else %}
      <div class="cd-small">No output quantity</div>
    {% endif %}
  {% endif %}
{% endmacro %}

{# ============================================================
   Table Counts
   ============================================================ #}

{% set purchase_count_ns = namespace(count=0) %}
{% set operation_count_ns = namespace(count=0) %}
{% set fixed_operation_count_ns = namespace(count=0) %}
{% set ratio_operation_count_ns = namespace(count=0) %}

{% for row in doc.materials or [] %}
  {% if row.material_item and frappe.utils.cint(row.include_in_purchase or 0) %}
    {% set purchase_count_ns.count = purchase_count_ns.count + 1 %}
  {% endif %}

  {% if row.material_item and frappe.utils.cint(row.include_in_production or 0) %}
    {% set operation_count_ns.count = operation_count_ns.count + 1 %}

    {% if (row.operation_qty_mode or "Recipe Ratio") == "Recipe Ratio" %}
      {% set ratio_operation_count_ns.count = ratio_operation_count_ns.count + 1 %}
    {% else %}
      {% set fixed_operation_count_ns.count = fixed_operation_count_ns.count + 1 %}
    {% endif %}
  {% endif %}
{% endfor %}

{# ============================================================
   Recipe Ratio Batch Totals
   Only Recipe Ratio materials are included.
   Fixed materials are excluded from operation basis.
   ============================================================ #}

{% set mix_ns = namespace(
  total_required=0,
  total_issue=0,
  has_mixed_uom=false,
  first_uom=""
) %}

{% for row in doc.materials or [] %}
  {% if row.material_item
        and frappe.utils.cint(row.include_in_production or 0)
        and (row.operation_qty_mode or "Recipe Ratio") == "Recipe Ratio" %}

    {% set demand_qty = frappe.utils.flt(material_required_qty(row, 0) or 0) %}
    {% set issue_qty = frappe.utils.flt(warehouse_issue_covered_qty(row, demand_qty) or 0) %}

    {% set mix_ns.total_required = mix_ns.total_required + demand_qty %}
    {% set mix_ns.total_issue = mix_ns.total_issue + issue_qty %}

    {% if not mix_ns.first_uom and row.uom %}
      {% set mix_ns.first_uom = row.uom %}
    {% endif %}

    {% if row.uom and mix_ns.first_uom and row.uom != mix_ns.first_uom %}
      {% set mix_ns.has_mixed_uom = true %}
    {% endif %}
  {% endif %}
{% endfor %}

{# ============================================================
   Standard Output Driver Material
   Used for non-batch cases.
   Fixed materials are excluded as output drivers.
   ============================================================ #}

{% set driver_ns = namespace(
  found=false,
  item="",
  item_ar="",
  required_qty=0,
  warehouse_issue_qty=0,
  uom="",
  capacity_qty=0,
  capacity_uom="",
  source=""
) %}

{% for row in doc.materials or [] %}
  {% if not driver_ns.found
        and row.material_item
        and frappe.utils.cint(row.include_in_production or 0)
        and (row.operation_qty_mode or "Recipe Ratio") == "Recipe Ratio"
        and (row.material__calculation_base or "Per Person") == "Output Driver" %}

    {% set driver_ns.found = true %}
    {% set driver_ns.item = row.material_item %}
    {% set driver_ns.item_ar = row.material_name_arabic or "" %}
    {% set driver_ns.required_qty = frappe.utils.flt(row.qty_per_person or 0) * person_qty %}
    {% set driver_ns.warehouse_issue_qty = frappe.utils.flt(warehouse_issue_covered_qty(row, driver_ns.required_qty) or 0) %}
    {% set driver_ns.uom = row.uom or "" %}

    {% if frappe.utils.flt(row.qty_per_output or 0) > 0 %}
      {% set driver_ns.capacity_qty = frappe.utils.flt(row.qty_per_output or 0) %}
      {% set driver_ns.capacity_uom = row.uom or "" %}
    {% elif input_same_as_output and output_capacity_qty > 0 %}
      {% set driver_ns.capacity_qty = output_capacity_qty %}
      {% set driver_ns.capacity_uom = row.uom or base_output_uom %}
    {% elif output_capacity_qty > 0 %}
      {% set driver_ns.capacity_qty = output_capacity_qty %}
      {% set driver_ns.capacity_uom = output_capacity_uom or row.uom or "" %}
    {% else %}
      {% set driver_ns.capacity_qty = 0 %}
      {% set driver_ns.capacity_uom = row.uom or "" %}
    {% endif %}

    {% set driver_ns.source = "Output Driver Material" %}
  {% endif %}
{% endfor %}

{% if not driver_ns.found %}
  {% for row in doc.materials or [] %}
    {% if not driver_ns.found
          and row.material_item
          and frappe.utils.cint(row.include_in_production or 0)
          and (row.operation_qty_mode or "Recipe Ratio") == "Recipe Ratio"
          and (row.material__calculation_base or "Per Person") == "Per Person" %}

      {% set driver_ns.found = true %}
      {% set driver_ns.item = row.material_item %}
      {% set driver_ns.item_ar = row.material_name_arabic or "" %}
      {% set driver_ns.required_qty = frappe.utils.flt(row.qty_per_person or 0) * person_qty %}
      {% set driver_ns.warehouse_issue_qty = frappe.utils.flt(warehouse_issue_covered_qty(row, driver_ns.required_qty) or 0) %}
      {% set driver_ns.uom = row.uom or "" %}

      {% if input_same_as_output and output_capacity_qty > 0 %}
        {% set driver_ns.capacity_qty = output_capacity_qty %}
        {% set driver_ns.capacity_uom = row.uom or base_output_uom %}
      {% elif output_capacity_qty > 0 %}
        {% set driver_ns.capacity_qty = output_capacity_qty %}
        {% set driver_ns.capacity_uom = output_capacity_uom or row.uom or "" %}
      {% else %}
        {% set driver_ns.capacity_qty = 0 %}
        {% set driver_ns.capacity_uom = row.uom or "" %}
      {% endif %}

      {% set driver_ns.source = "First Production Material" %}
    {% endif %}
  {% endfor %}
{% endif %}

{# ============================================================
   Output / Operation Qty
   ============================================================ #}

{% set output_ns = namespace(
  can=false,
  message="",
  raw=0,
  qty=0,
  actual_qty=0,
  basis_qty=0,
  basis_label="",
  output_label_uom=operation_uom
) %}

{% if requires_operation %}
  {% if mode_ns.batch_output %}
    {% if mix_ns.total_required > 0 and workstation_load_qty > 0 and output_capacity_qty > 0 %}
      {% set output_ns.can = true %}

      {% if use_full_warehouse_issue_qty and mix_ns.total_issue > 0 %}
        {% set output_ns.basis_qty = mix_ns.total_issue %}
        {% set output_ns.basis_label = "Full Warehouse Issue Qty for Recipe Ratio Materials" %}
      {% else %}
        {% set output_ns.basis_qty = mix_ns.total_required %}
        {% set output_ns.basis_label = "Required Qty for Recipe Ratio Materials" %}
      {% endif %}

      {% set output_ns.raw = (output_ns.basis_qty / workstation_load_qty) * output_capacity_qty %}
      {% set output_ns.qty = frappe.utils.flt(rounded_qty(output_ns.raw, output_rounding) or 0) %}

      {% if output_ns.qty <= 0 and output_ns.basis_qty > 0 %}
        {% set output_ns.qty = 1 %}
      {% endif %}

      {% set output_ns.actual_qty = output_ns.qty %}
      {% set output_ns.output_label_uom = base_output_uom %}
    {% else %}
      {% set output_ns.can = false %}
      {% set output_ns.message = "Batch output cannot be calculated. Please set at least one Recipe Ratio production material, Workstation Load Qty, and Output Container Capacity." %}
    {% endif %}

  {% elif driver_ns.found and driver_ns.capacity_qty > 0 %}
    {% set output_ns.can = true %}

    {% if use_full_warehouse_issue_qty and driver_ns.warehouse_issue_qty > 0 %}
      {% set output_ns.basis_qty = driver_ns.warehouse_issue_qty %}
      {% set output_ns.basis_label = "Full Warehouse Issue Qty" %}
    {% else %}
      {% set output_ns.basis_qty = driver_ns.required_qty %}
      {% set output_ns.basis_label = "Required Qty" %}
    {% endif %}

    {% set output_ns.raw = output_ns.basis_qty / driver_ns.capacity_qty %}
    {% set output_ns.qty = frappe.utils.flt(rounded_qty(output_ns.raw, output_rounding) or 0) %}

    {% if output_ns.qty <= 0 and output_ns.basis_qty > 0 %}
      {% set output_ns.qty = 1 %}
    {% endif %}

    {% set output_ns.actual_qty = output_ns.qty * driver_ns.capacity_qty %}
    {% set output_ns.output_label_uom = operation_uom %}
  {% else %}
    {% set output_ns.can = false %}
    {% set output_ns.message = "Output cannot be calculated. Please set output capacity or Qty Per Output and at least one Recipe Ratio production material." %}
  {% endif %}
{% else %}
  {% set output_ns.can = false %}
  {% set output_ns.message = "No site operation required." %}
{% endif %}

{# ============================================================
   Runs
   ============================================================ #}

{% if requires_operation and output_ns.can and workstation_load_qty > 0 %}
  {% set run_ns.can = true %}

  {% if mode_ns.batch_output %}
    {% set run_ns.basis_qty = output_ns.basis_qty %}
    {% set run_ns.basis_uom = "Run Basis Qty" %}
    {% set run_ns.raw = output_ns.basis_qty / workstation_load_qty %}
    {% set run_ns.formula = "Recipe Ratio Basis Qty ÷ Workstation Load Qty" %}

  {% elif workstation_load_uom == operation_uom %}
    {% set run_ns.basis_qty = output_ns.qty %}
    {% set run_ns.basis_uom = operation_uom %}
    {% set run_ns.raw = output_ns.qty / workstation_load_qty %}
    {% set run_ns.formula = "Operation Output Qty ÷ Workstation Load Qty" %}

  {% elif workstation_load_uom == driver_ns.uom %}
    {% set run_ns.basis_qty = output_ns.basis_qty %}
    {% set run_ns.basis_uom = driver_ns.uom %}
    {% set run_ns.raw = output_ns.basis_qty / workstation_load_qty %}
    {% set run_ns.formula = "Driver Qty ÷ Workstation Load Qty" %}

  {% else %}
    {% set run_ns.basis_qty = output_ns.qty %}
    {% set run_ns.basis_uom = operation_uom %}
    {% set run_ns.raw = output_ns.qty / workstation_load_qty %}
    {% set run_ns.formula = "Operation Output Qty ÷ Workstation Load Qty" %}
  {% endif %}

  {% set run_ns.qty = frappe.utils.flt(rounded_up(run_ns.raw) or 0) %}

  {% if run_ns.qty <= 0 and run_ns.basis_qty > 0 %}
    {% set run_ns.qty = 1 %}
  {% endif %}

  {% set run_ns.full_runs = run_ns.qty - 1 %}

  {% if run_ns.full_runs < 0 %}
    {% set run_ns.full_runs = 0 %}
  {% endif %}

  {% set run_ns.last_run_qty = run_ns.basis_qty - (run_ns.full_runs * workstation_load_qty) %}

  {% if run_ns.last_run_qty <= 0 and run_ns.basis_qty > 0 %}
    {% set run_ns.last_run_qty = workstation_load_qty %}
  {% endif %}
{% endif %}

<div class="cd-preview-wrapper">
  <div class="cd-card">

    <header class="cd-header">
      <div class="cd-title-row">
        <div class="cd-title-en">Catering Dish Calculation</div>
        <div class="cd-title-ar">نموذج حساب صنف التموين</div>
      </div>
    </header>

    <div class="cd-info-row">
      <span class="cd-badge"><strong>Dish:</strong> {{ doc.dish_name }}</span>

      {% if doc.dish_name_arabic %}
        <span class="cd-badge cd-rtl"><strong>الصنف:</strong> {{ doc.dish_name_arabic }}</span>
      {% endif %}

      {% if doc.default_section %}
        <span class="cd-badge"><strong>Section:</strong> {{ doc.default_section }}</span>
      {% endif %}

      <span class="cd-badge"><strong>Person Qty:</strong> {{ fmt(person_qty) }}</span>

      {% if requires_operation %}
        <span class="cd-badge cd-badge-success"><strong>Site Operation:</strong> Yes</span>
      {% else %}
        <span class="cd-badge"><strong>Site Operation:</strong> No</span>
      {% endif %}

      {% if mode_ns.batch_output %}
        <span class="cd-badge cd-badge-warning"><strong>Batch Output:</strong> Yes</span>
      {% endif %}

      {% if input_same_as_output %}
        <span class="cd-badge cd-badge-success"><strong>Input = Output:</strong> Yes</span>
      {% endif %}

      {% if use_full_warehouse_issue_qty %}
        <span class="cd-badge cd-badge-warning"><strong>Full Warehouse Issue:</strong> Yes</span>
      {% else %}
        <span class="cd-badge"><strong>Full Warehouse Issue:</strong> No</span>
      {% endif %}

      {% if doc.default_workstation and requires_operation %}
        <span class="cd-badge"><strong>Workstation:</strong> {{ doc.default_workstation }}</span>
      {% endif %}

      {% if output_ns.can %}
        <span class="cd-badge">
          <strong>Operation Output:</strong>
          {{ fmt(output_ns.qty) }} {{ output_ns.output_label_uom }}
        </span>
      {% endif %}

      {% if run_ns.can %}
        <span class="cd-badge"><strong>Runs:</strong> {{ fmt(run_ns.qty) }}</span>
      {% elif not requires_operation %}
        <span class="cd-badge"><strong>Runs:</strong> 0</span>
      {% endif %}
    </div>

    {% if purchase_count_ns.count > 0 %}
      <div class="cd-operation-header">
        <span class="cd-operation-title-en">Required & Purchase</span>
        <span class="cd-operation-title-ar">المطلوب والشراء</span>
      </div>

      <table class="cd-table">
        <thead>
          <tr>
            <th>
              <div class="bi-head">
                <div class="en">Material</div>
                <div class="ar">المادة</div>
              </div>
            </th>

            <th>
              <div class="bi-head">
                <div class="en">Required Qty</div>
                <div class="ar">الكمية المطلوبة</div>
              </div>
            </th>

            <th>
              <div class="bi-head">
                <div class="en">Purchase Qty</div>
                <div class="ar">كمية الشراء</div>
              </div>
            </th>
          </tr>
        </thead>

        <tbody>
          {% for row in doc.materials or [] %}
            {% if row.material_item and frappe.utils.cint(row.include_in_purchase or 0) %}
              {% set material_base = row.material__calculation_base or "Per Person" %}
              {% set op_mode = row.operation_qty_mode or "Recipe Ratio" %}
              {% set demand_qty = frappe.utils.flt(material_required_qty(row, output_ns.qty) or 0) %}

              <tr>
                <td class="item-col">
                  <div>{{ row.material_name or row.material_item }}</div>

                  {% if row.material_name_arabic %}
                    <div class="item-name-ar">{{ row.material_name_arabic }}</div>
                  {% endif %}

                  <div class="cd-small">{{ row.material_item }}</div>
                  <div class="cd-small">
                    Base: {{ material_base }}
                    |
                    Operation Mode: {{ op_mode }}
                    |
                    Display: {{ row.operation_display_uom_mode or "Receiving UOM" }}
                    |
                    Purchase: Yes
                    |
                    Production: {{ yes_no(row.include_in_production) }}
                  </div>
                </td>

                <td>
                  <span class="cd-number">{{ fmt(demand_qty) }}</span>
                  <span class="cd-uom-small">{{ uom_short(row.uom) }}</span>
                  {{ required_qty_note(row, demand_qty, output_ns.qty) }}
                </td>

                <td>
                  <span class="cd-number">{{ purchase_qty_display(row, demand_qty) }}</span>
                  {{ purchase_qty_note(row, demand_qty) }}
                </td>
              </tr>
            {% endif %}
          {% endfor %}
        </tbody>
      </table>
    {% endif %}

    {% if operation_count_ns.count > 0 %}
      <div class="cd-operation-header">
        <span class="cd-operation-title-en">Warehouse Issue & Operation</span>
        <span class="cd-operation-title-ar">الصرف من المستودع والتشغيل</span>
      </div>

      <table class="cd-table">
        <thead>
          <tr>
            <th>
              <div class="bi-head">
                <div class="en">Material</div>
                <div class="ar">المادة</div>
              </div>
            </th>

            <th>
              <div class="bi-head">
                <div class="en">Warehouse Issue</div>
                <div class="ar">الصرف من المستودع</div>
              </div>
            </th>

            <th>
              <div class="bi-head">
                {% if mode_ns.batch_output %}
                  <div class="en">Qty / Full Run or Group</div>
                  <div class="ar">الكمية / تشغيله أو مجموعة</div>
                {% else %}
                  <div class="en">Qty / {{ operation_uom }}</div>
                  <div class="ar">الكمية / {{ operation_uom }}</div>
                {% endif %}
              </div>
            </th>

            <th>
              <div class="bi-head">
                <div class="en">Runs</div>
                <div class="ar">مرات التشغيل</div>
              </div>
            </th>
          </tr>
        </thead>

        <tbody>
          {% for row in doc.materials or [] %}
            {% if row.material_item and frappe.utils.cint(row.include_in_production or 0) %}
              {% set op_mode = row.operation_qty_mode or "Recipe Ratio" %}
              {% set demand_qty = frappe.utils.flt(material_required_qty(row, output_ns.qty) or 0) %}
              {% set operation_qty = frappe.utils.flt(material_operation_qty(row, demand_qty, output_ns.qty) or 0) %}
              {% set issue_covered_qty = frappe.utils.flt(warehouse_issue_covered_qty(row, demand_qty) or 0) %}
              {% set is_driver_row = (row.material_item == driver_ns.item) %}

              <tr>
                <td class="item-col">
                  <div>{{ row.material_name or row.material_item }}</div>

                  {% if row.material_name_arabic %}
                    <div class="item-name-ar">{{ row.material_name_arabic }}</div>
                  {% endif %}

                  <div class="cd-small">{{ row.material_item }}</div>
                  <div class="cd-small">Operation Mode: {{ op_mode }}</div>
                  <div class="cd-small">Display: {{ row.operation_display_uom_mode or "Receiving UOM" }}</div>
                </td>

                <td>
                  <span class="cd-number">{{ warehouse_issue_display(row, demand_qty) }}</span>
                  {{ warehouse_issue_note(row, demand_qty) }}

                  {% if use_full_warehouse_issue_qty and op_mode == "Recipe Ratio" and issue_covered_qty != demand_qty %}
                    <div class="cd-small cd-warning">
                      Full issue used for operation:
                      {{ fmt(issue_covered_qty) }} {{ row.uom }}
                    </div>
                  {% endif %}
                </td>

                <td>
                  {% if requires_operation and output_ns.can %}
                    {% if mode_ns.batch_output and op_mode == "Recipe Ratio" %}
                      {% set issue_qty = frappe.utils.flt(warehouse_issue_covered_qty(row, demand_qty) or 0) %}

                      {% if use_full_warehouse_issue_qty and issue_qty > 0 %}
                        {% set basis_material_qty = issue_qty %}
                      {% else %}
                        {% set basis_material_qty = demand_qty %}
                      {% endif %}

                      {% set ratio = basis_material_qty / output_ns.basis_qty %}
                      {% set raw_full_run_qty = workstation_load_qty * ratio %}
                      {% set full_run_qty = raw_full_run_qty %}
                      {% set last_run_material_qty = basis_material_qty - (raw_full_run_qty * run_ns.full_runs) %}

                      {% if (row.uom or "") in batch_round_uoms %}
                        {% set full_run_qty = frappe.utils.flt(rounded_qty(raw_full_run_qty, "Half Round") or 0) %}
                        {% set last_run_material_qty = basis_material_qty - (full_run_qty * run_ns.full_runs) %}

                        {% if last_run_material_qty < 0 %}
                          {% set full_run_qty = raw_full_run_qty|int %}
                          {% set last_run_material_qty = basis_material_qty - (full_run_qty * run_ns.full_runs) %}
                        {% endif %}

                        {% set last_run_material_qty = frappe.utils.flt(rounded_qty(last_run_material_qty, "Half Round") or 0) %}
                      {% endif %}

                      <span class="cd-number">
                        {{ operation_qty_display(row, full_run_qty) }}
                      </span>

                      {{ operation_qty_display_note(row, full_run_qty) }}

                      <div class="cd-small">
                        Ratio: {{ fmt(ratio * 100) }}%
                      </div>

                      <div class="cd-small">
                        Last run:
                        {{ operation_qty_display(row, last_run_material_qty) }}
                      </div>

                      {{ operation_qty_display_note(row, last_run_material_qty) }}

                    {% elif op_mode == "Fixed Once" %}
                      <span class="cd-number">
                        {{ operation_qty_display(row, row.fixed_operation_qty) }}
                      </span>

                      {{ operation_qty_display_note(row, row.fixed_operation_qty) }}

                      <div class="cd-small">
                        Fixed once only.
                      </div>

                      <div class="cd-small">
                        Total operation qty:
                        {{ operation_qty_display(row, operation_qty) }}
                      </div>

                    {% elif op_mode == "Fixed Every N Runs" %}
                      {% set freq = frappe.utils.cint(row.operation_run_frequency or 1) %}
                      {% if freq <= 0 %}
                        {% set freq = 1 %}
                      {% endif %}
                      {% set times = frappe.utils.flt(fixed_operation_times(row) or 0) %}

                      <span class="cd-number">
                        {{ operation_qty_display(row, row.fixed_operation_qty) }}
                      </span>

                      {{ operation_qty_display_note(row, row.fixed_operation_qty) }}

                      <div class="cd-small">
                        Every {{ fmt(freq) }} Runs
                      </div>

                      <div class="cd-small">
                        Times:
                        {{ fmt(run_ns.qty) }} ÷ {{ fmt(freq) }}
                        =
                        {{ fmt(run_ns.qty / freq) }}
                        →
                        {{ fmt(times) }}
                      </div>

                      <div class="cd-small">
                        Total operation qty:
                        {{ operation_qty_display(row, operation_qty) }}
                      </div>

                    {% else %}
                      <span class="cd-number">{{ qty_per_output_display(row, operation_qty, output_ns.qty) }}</span>
                      {{ qty_per_output_note(row, operation_qty, output_ns.qty) }}
                    {% endif %}

                  {% elif not output_ns.can %}
                    <span class="cd-muted">Missing Output</span>
                  {% else %}
                    <span class="cd-muted">No Operation</span>
                  {% endif %}
                </td>

                <td>
                  {% if requires_operation and run_ns.can %}
                    <span class="cd-number">{{ fmt(run_ns.qty) }}</span>
                    <div class="cd-small">
                      {{ fmt(run_ns.basis_qty) }} {{ run_ns.basis_uom }}
                      ÷
                      {{ fmt(workstation_load_qty) }}
                      =
                      {{ fmt(run_ns.raw) }}
                      →
                      {{ fmt(run_ns.qty) }}
                    </div>

                    <div class="cd-small">
                      Last run:
                      {{ fmt(run_ns.last_run_qty) }} {{ run_ns.basis_uom }}
                    </div>
                  {% elif not requires_operation %}
                    <span class="cd-number">0</span>
                    <div class="cd-small">No site operation</div>
                  {% else %}
                    <span class="cd-muted">-</span>
                  {% endif %}
                </td>
              </tr>
            {% endif %}
          {% endfor %}
        </tbody>
      </table>
    {% endif %}

    {% if fixed_operation_count_ns.count > 0 %}
      <div class="cd-notes-block">
        <div class="cd-notes-title">Fixed Operation Materials / مواد تشغيل ثابتة</div>
        <div class="cd-note-line">
          Fixed materials are excluded from operation output calculation. They are calculated after Runs are known.
        </div>
      </div>
    {% endif %}

    {% if doc.cooking_instructions %}
      <div class="cd-notes-block">
        <div class="cd-notes-title">Notes / ملاحظات</div>
        <div class="cd-note-line">{{ doc.cooking_instructions }}</div>
      </div>
    {% endif %}

    <div class="cd-calc-block">
      <div class="cd-calc-title">Calculation Breakdown / شرح طريقة الحساب</div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">1) Main Setup / الإعدادات الأساسية</div>

        <div class="cd-calc-line">
          Person Qty =
          <strong>{{ fmt(person_qty) }}</strong>
        </div>

        <div class="cd-calc-line">
          Requires Site Operation =
          <strong>{{ yes_no(doc.requires_workstation) }}</strong>
        </div>

        <div class="cd-calc-line">
          Input Qty/UOM Same as Output =
          <strong>{{ yes_no(doc.input_qtyuom_same_as_output) }}</strong>
        </div>

        <div class="cd-calc-line">
          Batch Output Mode =
          <strong>{{ yes_no(mode_ns.batch_output) }}</strong>
        </div>

        <div class="cd-calc-line">
          Recipe Ratio Materials =
          <strong>{{ fmt(ratio_operation_count_ns.count) }}</strong>
        </div>

        <div class="cd-calc-line">
          Fixed Operation Materials =
          <strong>{{ fmt(fixed_operation_count_ns.count) }}</strong>
        </div>

        <div class="cd-calc-line">
          Operation Unit =
          <strong>{{ operation_uom }}</strong>
        </div>

        <div class="cd-calc-line">
          Use Full Warehouse Issue Qty =
          <strong>{{ yes_no(doc.use_full_warehouse_issue_qty) }}</strong>
        </div>

        {% if requires_operation %}
          <div class="cd-calc-line">
            Workstation =
            <strong>{{ doc.default_workstation or "-" }}</strong>
          </div>

          <div class="cd-calc-line">
            Workstation Load =
            <strong>{{ fmt(workstation_load_qty) }}</strong>
          </div>

          <div class="cd-calc-line">
            Output Container =
            <strong>{{ base_output_uom }}</strong>
          </div>

          <div class="cd-calc-line">
            Output Per Full Run =
            <strong>{{ fmt(output_capacity_qty) }} {{ output_capacity_uom }}</strong>
          </div>

          <div class="cd-calc-line">
            Output Rounding Method =
            <strong>{{ round_text(output_rounding) }}</strong>
          </div>
        {% endif %}
      </div>

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">2) Output / Operation Qty / كمية المخرج أو التشغيل</div>

        {% if output_ns.can %}
          {% if mode_ns.batch_output %}
            <div class="cd-calc-line">
              Required Qty for Recipe Ratio Materials =
              <strong>{{ fmt(mix_ns.total_required) }}</strong>
            </div>

            {% if use_full_warehouse_issue_qty %}
              <div class="cd-calc-line">
                Full Warehouse Issue Qty for Recipe Ratio Materials =
                <strong>{{ fmt(mix_ns.total_issue) }}</strong>
              </div>
            {% endif %}

            <div class="cd-calc-line">
              Operation Basis =
              <strong>{{ output_ns.basis_label }} = {{ fmt(output_ns.basis_qty) }}</strong>
            </div>

            <div class="cd-calc-line">
              Output Raw =
              Operation Basis ÷ Workstation Load × Output Per Full Run =
              {{ fmt(output_ns.basis_qty) }}
              ÷
              {{ fmt(workstation_load_qty) }}
              ×
              {{ fmt(output_capacity_qty) }} {{ base_output_uom }}
              =
              <strong>{{ fmt(output_ns.raw) }} {{ base_output_uom }}</strong>
            </div>

            <div class="cd-calc-line">
              Operation Output Qty =
              {{ round_text(output_rounding) }}({{ fmt(output_ns.raw) }})
              =
              <strong>{{ fmt(output_ns.qty) }} {{ base_output_uom }}</strong>
            </div>

          {% else %}
            <div class="cd-calc-line">
              Output Driver =
              <strong>{{ driver_ns.item }}</strong>
              {% if driver_ns.source %}
                <span class="cd-muted">({{ driver_ns.source }})</span>
              {% endif %}
            </div>

            <div class="cd-calc-line">
              Required Driver Qty =
              <strong>{{ fmt(driver_ns.required_qty) }} {{ driver_ns.uom }}</strong>
            </div>

            {% if use_full_warehouse_issue_qty %}
              <div class="cd-calc-line">
                Full Warehouse Issue Qty =
                <strong>{{ fmt(driver_ns.warehouse_issue_qty) }} {{ driver_ns.uom }}</strong>
              </div>
            {% endif %}

            <div class="cd-calc-line">
              Operation Basis =
              <strong>{{ output_ns.basis_label }} = {{ fmt(output_ns.basis_qty) }} {{ driver_ns.uom }}</strong>
            </div>

            <div class="cd-calc-line">
              Operation Output Raw =
              {{ fmt(output_ns.basis_qty) }} {{ driver_ns.uom }}
              ÷
              {{ fmt(driver_ns.capacity_qty) }} {{ driver_ns.capacity_uom }}
              =
              <strong>{{ fmt(output_ns.raw) }} {{ operation_uom }}</strong>
            </div>

            <div class="cd-calc-line">
              Operation Output Qty =
              {{ round_text(output_rounding) }}({{ fmt(output_ns.raw) }})
              =
              <strong>{{ fmt(output_ns.qty) }} {{ operation_uom }}</strong>
            </div>
          {% endif %}
        {% else %}
          <div class="cd-calc-line cd-muted">
            {{ output_ns.message }}
          </div>
        {% endif %}
      </div>

      {% if mode_ns.batch_output and output_ns.can and output_ns.basis_qty > 0 %}
        <div class="cd-calc-section">
          <div class="cd-calc-section-title">3) Recipe Ratio Material Distribution / توزيع مواد النسبة على التشغيلات</div>

          <table class="cd-mini-table">
            <thead>
              <tr>
                <th>Material</th>
                <th>Basis Qty</th>
                <th>Mix %</th>
                <th>Full Run Qty</th>
                <th>Last Run Qty</th>
              </tr>
            </thead>

            <tbody>
              {% for row in doc.materials or [] %}
                {% if row.material_item
                      and frappe.utils.cint(row.include_in_production or 0)
                      and (row.operation_qty_mode or "Recipe Ratio") == "Recipe Ratio" %}

                  {% set demand_qty = frappe.utils.flt(material_required_qty(row, 0) or 0) %}
                  {% set issue_qty = frappe.utils.flt(warehouse_issue_covered_qty(row, demand_qty) or 0) %}

                  {% if use_full_warehouse_issue_qty and issue_qty > 0 %}
                    {% set basis_material_qty = issue_qty %}
                  {% else %}
                    {% set basis_material_qty = demand_qty %}
                  {% endif %}

                  {% set ratio = basis_material_qty / output_ns.basis_qty %}
                  {% set raw_full_run_qty = workstation_load_qty * ratio %}
                  {% set full_run_qty = raw_full_run_qty %}
                  {% set last_run_material_qty = basis_material_qty - (raw_full_run_qty * run_ns.full_runs) %}

                  {% if (row.uom or "") in batch_round_uoms %}
                    {% set full_run_qty = frappe.utils.flt(rounded_qty(raw_full_run_qty, "Half Round") or 0) %}
                    {% set last_run_material_qty = basis_material_qty - (full_run_qty * run_ns.full_runs) %}

                    {% if last_run_material_qty < 0 %}
                      {% set full_run_qty = raw_full_run_qty|int %}
                      {% set last_run_material_qty = basis_material_qty - (full_run_qty * run_ns.full_runs) %}
                    {% endif %}

                    {% set last_run_material_qty = frappe.utils.flt(rounded_qty(last_run_material_qty, "Half Round") or 0) %}
                  {% endif %}

                  <tr>
                    <td>{{ row.material_name or row.material_item }}</td>
                    <td>{{ operation_qty_display(row, basis_material_qty) }}</td>
                    <td>{{ fmt(ratio * 100) }}%</td>
                    <td>{{ operation_qty_display(row, full_run_qty) }}</td>
                    <td>{{ operation_qty_display(row, last_run_material_qty) }}</td>
                  </tr>
                {% endif %}
              {% endfor %}
            </tbody>
          </table>
        </div>
      {% endif %}

      {% if fixed_operation_count_ns.count > 0 and run_ns.can %}
        <div class="cd-calc-section">
          <div class="cd-calc-section-title">4) Fixed Operation Materials / المواد الثابتة في التشغيل</div>

          <table class="cd-mini-table">
            <thead>
              <tr>
                <th>Material</th>
                <th>Mode</th>
                <th>Fixed Qty</th>
                <th>Frequency</th>
                <th>Times</th>
                <th>Total Qty</th>
              </tr>
            </thead>

            <tbody>
              {% for row in doc.materials or [] %}
                {% if row.material_item
                      and frappe.utils.cint(row.include_in_production or 0)
                      and (row.operation_qty_mode or "Recipe Ratio") != "Recipe Ratio" %}

                  {% set op_mode = row.operation_qty_mode or "Recipe Ratio" %}
                  {% set times = frappe.utils.flt(fixed_operation_times(row) or 0) %}
                  {% set total_fixed_qty = frappe.utils.flt(fixed_operation_required_qty(row) or 0) %}
                  {% set freq = frappe.utils.cint(row.operation_run_frequency or 1) %}

                  {% if freq <= 0 %}
                    {% set freq = 1 %}
                  {% endif %}

                  <tr>
                    <td>{{ row.material_name or row.material_item }}</td>
                    <td>{{ op_mode }}</td>
                    <td>{{ operation_qty_display(row, row.fixed_operation_qty) }}</td>
                    <td>
                      {% if op_mode == "Fixed Every N Runs" %}
                        Every {{ fmt(freq) }} Runs
                      {% else %}
                        Once
                      {% endif %}
                    </td>
                    <td>{{ fmt(times) }}</td>
                    <td>{{ operation_qty_display(row, total_fixed_qty) }}</td>
                  </tr>
                {% endif %}
              {% endfor %}
            </tbody>
          </table>
        </div>
      {% endif %}

      <div class="cd-calc-section">
        <div class="cd-calc-section-title">
          {% if fixed_operation_count_ns.count > 0 %}
            5) Runs / مرات التشغيل
          {% elif mode_ns.batch_output %}
            4) Runs / مرات التشغيل
          {% else %}
            3) Runs / مرات التشغيل
          {% endif %}
        </div>

        {% if run_ns.can %}
          <div class="cd-calc-line">
            Run Basis =
            <strong>{{ fmt(run_ns.basis_qty) }} {{ run_ns.basis_uom }}</strong>
          </div>

          <div class="cd-calc-line">
            Workstation Load =
            <strong>{{ fmt(workstation_load_qty) }}</strong>
          </div>

          <div class="cd-calc-line">
            Runs Raw =
            {{ run_ns.formula }}
            =
            {{ fmt(run_ns.basis_qty) }}
            ÷
            {{ fmt(workstation_load_qty) }}
            =
            <strong>{{ fmt(run_ns.raw) }}</strong>
          </div>

          <div class="cd-calc-line">
            Runs =
            Round Up({{ fmt(run_ns.raw) }})
            =
            <strong>{{ fmt(run_ns.qty) }}</strong>
          </div>

          <div class="cd-calc-line">
            Last Run Qty =
            <strong>{{ fmt(run_ns.last_run_qty) }} {{ run_ns.basis_uom }}</strong>
          </div>

        {% elif not requires_operation %}
          <div class="cd-calc-line">
            Runs =
            <strong>0</strong>
            because this dish does not require site operation.
          </div>
        {% else %}
          <div class="cd-calc-line cd-danger">
            Runs cannot be calculated because Operation Output Qty or Workstation Load Qty is missing.
          </div>
        {% endif %}
      </div>
    </div>

    <table class="cd-table cd-output-table">
      <thead>
        <tr>
          <th>
            <div class="bi-head">
              <div class="en">Dish</div>
              <div class="ar">الصنف</div>
            </div>
          </th>

          <th>
            <div class="bi-head">
              <div class="en">Operation Output</div>
              <div class="ar">مخرج التشغيل</div>
            </div>
          </th>

          <th>
            <div class="bi-head">
              <div class="en">Workstation Load</div>
              <div class="ar">حمولة التشغيل</div>
            </div>
          </th>

          <th>
            <div class="bi-head">
              <div class="en">Runs</div>
              <div class="ar">مرات التشغيل</div>
            </div>
          </th>

          <th>
            <div class="bi-head">
              <div class="en">Status</div>
              <div class="ar">الحالة</div>
            </div>
          </th>
        </tr>
      </thead>

      <tbody>
        <tr>
          <td class="item-col">
            <div>{{ doc.dish_name }}</div>
            {% if doc.dish_name_arabic %}
              <div class="item-name-ar">{{ doc.dish_name_arabic }}</div>
            {% endif %}
          </td>

          <td>
            {% if output_ns.can %}
              <span class="cd-output-number">{{ fmt(output_ns.qty) }}</span>
              <span class="cd-output-uom">{{ output_ns.output_label_uom }}</span>
            {% else %}
              <span class="cd-muted">-</span>
            {% endif %}
          </td>

          <td>
            {% if run_ns.can %}
              <span class="cd-output-number">{{ fmt(workstation_load_qty) }}</span>
            {% elif not requires_operation %}
              <span class="cd-output-number">0</span>
            {% else %}
              <span class="cd-muted">-</span>
            {% endif %}
          </td>

          <td>
            {% if run_ns.can %}
              <span class="cd-output-number">{{ fmt(run_ns.qty) }}</span>
              <div class="cd-small">
                Last run: {{ fmt(run_ns.last_run_qty) }} {{ run_ns.basis_uom }}
              </div>
            {% elif not requires_operation %}
              <span class="cd-output-number">0</span>
            {% else %}
              <span class="cd-muted">-</span>
            {% endif %}
          </td>

          <td>
            {% if requires_operation %}
              {% if output_ns.can %}
                {% if fixed_operation_count_ns.count > 0 %}
                  <span class="cd-success">Operation with Fixed Materials</span>
                {% elif mode_ns.batch_output %}
                  <span class="cd-success">Batch Output</span>
                {% else %}
                  <span class="cd-success">Site Operation Required</span>
                {% endif %}
              {% else %}
                <span class="cd-warning">Missing Setup</span>
              {% endif %}
            {% else %}
              <span class="cd-muted">No Site Operation</span>
            {% endif %}
          </td>
        </tr>
      </tbody>
    </table>

  </div>
</div>
